    Clock clock;

    // 注册学生观察者
    for (int i = 0; i &lt; N; i++) {
        std::string studentName;
        std::cin &gt;&gt; studentName;
        clock.registerObserver(new Student(studentName));
    }

    // 读取时钟更新次数
    int updates;
    std::cin &gt;&gt; updates;

    // 模拟时钟每隔一个小时更新一次
    for (int i = 0; i &lt; updates; i++) {
        clock.tick();
    }

    // 释放动态分配的观察者对象
    for (Observer* observer : clock.getObservers()) {
        delete observer;
    }

    return 0;
}
