TypeScript<pre><code>interface ISubject {
  add(observer: IObserver): void;
  remove(observer: IObserver): void;
  notify(msg: string): void;
}

interface IObserver {
  update(msg: string): void;
}

class Clock implements ISubject {
  private observers: IObserver[]

  constructor() {
    this.observers = [];
  }

  add(observer: IObserver) {
    this.observers.push(observer);
  }

  remove(observer: IObserver) {
    this.observers = this.observers.filter((item) =&gt; item!== observer);
  }

  notify(msg: string) {
    this.observers.forEach((item) =&gt; {
      item.update(msg);
    });
  }
}

class Student implements IObserver {
  name: string;
  constructor(name: string) {
    this.name = name;
  }
  update(msg: string) {
    console.log(`${this.name} ${msg}`);
  }
}

// @ts-ignore
entry(2, (...args) =&gt; {
  return (time: number) =&gt; {
    const timeSubject = new Clock();
    args.forEach((item) =&gt; {
      timeSubject.add(new Student(item));
    });

    for (let i = 1; i &lt;= time; i++) {
      timeSubject.notify(i.toString());
    }
  };
})("Alice")("Bob")(3);

function entry(count: number, fn: (...args: any) =&gt; void) {
  function dfs(...args) {
    if (args.length &lt; count) {
      return (arg) =&gt; dfs(...args, arg);
    }
    return fn(...args);
  }
  return dfs;
}
