func main() {
    s := make(chan struct{})
    //通过map的key来保证协程的顺序
    m := make(map[int]chan int, 100)
    //填充map,初始化channel
    for i := 1; i &lt;= 100; i++ {
        m[i] = make(chan int)
    }
    //开启100个协程，死循环打印
    for i := 1; i &lt;= 100; i++ {
        go func(id int) {
            for {
                num := &lt;-m[id]
                fmt.Println(num)
                s &lt;- struct{}{}
            }
        }(i)
    }
    //循环1-1000，并把值传递给匹配的map
    //然后通过s限制循序打印
    for i := 1; i &lt;= 1000; i++ {
        id := i % 100
        if id == 0 {
            id = 100
        }
        m[id] &lt;- i
        //通过s这个来控制打印顺序。每次遍历一次i
        //都通过s阻塞协程的打印，最后打印完毕
        &lt;-s
    }

    time.Sleep(10 * time.Second)
}
